// Validar Hora Pico USA (America/New_York)
const now = new Date();
const inputData = $input.first()?.json || {};

// Comprobar si se ha solicitado despacho forzado (override manual)
const isForced = inputData.force_dispatch === true || inputData.body?.force_dispatch === true;

// Obtener hora y minutos actuales en la zona horaria oficial del mercado objetivo USA
const estTimeFormatter = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/New_York',
  hour: 'numeric',
  minute: 'numeric',
  hour12: false
});

const estParts = estTimeFormatter.formatToParts(now);
let estHour = 0;
let estMinute = 0;
for (const part of estParts) {
  if (part.type === 'hour') estHour = parseInt(part.value, 10);
  if (part.type === 'minute') estMinute = parseInt(part.value, 10);
}

// Convertir hora y minutos a minutos acumulados del día
const totalEstMinutes = (estHour * 60) + estMinute;

// Ventanas Pico Oficiales de Alto Impacto USA (±30 minutos de holgura):
// Ventana 1: 11:00 AM EST -> 660 min (Rango: 10:30 a 11:30 = 630 a 690 min)
// Ventana 2: 07:00 PM EST -> 1140 min (Rango: 18:30 a 19:30 = 1110 a 1170 min)
const isWindow11AM = (totalEstMinutes >= 630 && totalEstMinutes <= 690);
const isWindow7PM = (totalEstMinutes >= 1110 && totalEstMinutes <= 1170);

let activeSlot = null;
if (isWindow11AM) activeSlot = '11:00 AM EST (Almuerzo USA)';
else if (isWindow7PM) activeSlot = '07:00 PM EST (Prime Nocturno USA)';
else if (isForced) activeSlot = 'Manual Override (Forzado)';

const isPeakWindow = isForced || isWindow11AM || isWindow7PM;

return [{
  json: {
    is_peak_window: isPeakWindow,
    active_slot: activeSlot,
    est_hour: estHour,
    est_minute: estMinute,
    est_formatted: `${String(estHour).padStart(2, '0')}:${String(estMinute).padStart(2, '0')} EST`,
    force_applied: isForced,
    timestamp_utc: now.toISOString(),
    status: isPeakWindow ? 'PEAK_VALIDATED' : 'OFF_PEAK_SKIPPED',
    message: isPeakWindow 
      ? `Ventana pico confirmada: ${activeSlot}` 
      : `Fuera de ventana pico (${estHour}:${estMinute} EST). Postergando despacho.`
  }
}];

// Desglosar la lista devuelta por NocoDB en items individuales
const inputData = $input.first().json;
const rawList = inputData.list || (Array.isArray(inputData) ? inputData : []);

if (!rawList || rawList.length === 0) {
  return [];
}

return rawList.map(record => ({
  json: {
    queue_id: record.Id || record.id,
    business_id: record.business_id || 'general-winner',
    business_name: record.business_name || 'Negocio Antigravity',
    product_name: record.product_name || 'Producto Ganador',
    niche: record.niche || 'General',
    video_url: record.video_url,
    title_raw: record.title || 'Ganador Increíble que Debes Ver',
    description_raw: record.description || '',
    tags_raw: record.tags || 'dropshipping, viral, tech, trending, usa',
    hook_type: record.hook_type || 'Curiosidad Disruptiva',
    checkout_url: record.checkout_url || 'https://antigravity-hub.internal',
    ig_user_id: record.ig_user_id || '17841400000000000',
    fb_page_id: record.fb_page_id || '100000000000000',
    created_at: record.CreatedAt || new Date().toISOString()
  }
}));

// Sanitizar Metadatos y Anti-Spam para Triada de Oro
const item = $input.item.json;

// 1. Sanitizar Título:
// - Quitar caracteres especiales peligrosos y etiquetas HTML
// - Limitar longitud estrictamente a <100 caracteres (máx 85 para dar margen seguro a tags)
let cleanTitle = (item.title_raw || '')
  .replace(/<[^>]*>?/gm, '')
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/["'`]/g, '')
  .replace(/\s{2,}/g, ' ')
  .trim();

if (cleanTitle.length > 85) {
  cleanTitle = cleanTitle.substring(0, 82).trim() + '...';
}

// Para YouTube Shorts, el tag #shorts es crítico para el shelf
const ytTitle = `${cleanTitle} #shorts`;

// 2. Sanitizar Hashtags y Tags
let rawTags = (item.tags_raw || 'dropshipping, viral, tiktokmademebuyit, usa, lifehack')
  .split(/[,\s]+/)
  .map(t => t.replace(/^#/, '').trim().toLowerCase())
  .filter(t => t.length > 1);

// Unificar y deduplicar
const uniqueTags = Array.from(new Set(rawTags)).slice(0, 8);
const formattedHashtags = uniqueTags.map(t => `#${t}`).join(' ');

// 3. Sanitizar y formatear descripción YouTube
const ytDescription = `${cleanTitle}

🔥 Get yours now before stock runs out: ${item.checkout_url}
📦 Fast 7-12 days delivery across USA. 30-Day Money Back Guarantee.

${formattedHashtags} #shorts #viral #antigravity #trending
Audio: Google Cloud Neural2 (Verified Unique Render)`;

// 4. Sanitizar y formatear Caption de Instagram Reels
const igCaption = `${cleanTitle} 🤯

👇 Tap the link in bio to get yours with 50% OFF today!
🚚 Free Tracked Shipping to USA
✨ Limited stock available!

.
.
${formattedHashtags} #reels #viralvideos #reelsinstagram #shopnow`;

// 5. Sanitizar y formatear Descripción de Facebook Reels
const fbDescription = `Watch this transformation! 💥 ${cleanTitle}
👉 Direct checkout link: ${item.checkout_url}
Get 50% discount and fast domestic shipping today!`;

return [{
  json: {
    ...item,
    sanitized_title: cleanTitle,
    yt_title: ytTitle,
    yt_description: ytDescription,
    yt_tags: uniqueTags,
    ig_caption: igCaption,
    fb_description: fbDescription,
    anti_spam_hash: `phash_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`,
    sanitized_at: new Date().toISOString()
  }
}];

