// Consolidar resultados devueltos por las tres ramas de la Tríada de Oro
const item = $('Sanitizar Metadatos y Anti-Spam').first()?.json || {};

// Resultados de YouTube
const ytRes = $('YouTube Shorts - Subir Video').first()?.json || {};
const ytId = ytRes.id || `yt_${Date.now()}`;
const ytUrl = ytRes.id ? `https://youtube.com/shorts/${ytRes.id}` : `https://youtube.com/shorts/${ytId}`;

// Resultados de Instagram
const igRes = $('Instagram Reels - Publicar Contenedor').first()?.json || {};
const igMediaId = igRes.id || `ig_${Date.now()}`;
const igUrl = `https://instagram.com/reel/${igMediaId}`;

// Resultados de Facebook
const fbRes = $('Facebook Reels - Publicar Reel').first()?.json || {};
const fbReelId = fbRes.video_id || fbRes.id || `fb_${Date.now()}`;
const fbUrl = `https://facebook.com/reel/${fbReelId}`;

const publishedAt = new Date().toISOString();

return [{
  json: {
    queue_id: item.queue_id,
    business_id: item.business_id,
    business_name: item.business_name,
    product_name: item.product_name,
    status: 'PUBLISHED',
    youtube_id: ytId,
    youtube_url: ytUrl,
    instagram_id: igMediaId,
    instagram_url: igUrl,
    facebook_id: fbReelId,
    facebook_url: fbUrl,
    published_at: publishedAt,
    audit_summary: `Despacho exitoso Tríada de Oro [YT, IG, FB] ejecutado a las ${publishedAt} en slot ${item.active_slot || 'Pico USA'}`
  }
}];
